effects.glsl:
mat2 psyRotate(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c, -s, s, c);
}

vec3 psySpectrum(float h) {
    vec3 wheel = 0.54 + 0.46 * cos(6.2831853 * (h + vec3(0.00, 0.67, 0.33)));
    vec3 ramp = mix(palette(4), palette(6), 0.5 + 0.5 * sin(h * 6.2831853));
    ramp = mix(ramp, palette(7), 0.22 + 0.18 * cos(h * 12.5663706));
    return mix(ramp, wheel, 0.58);
}

vec4 effect(vec2 uv, vec4 src) {
    float aspect = uResolution.x / max(uResolution.y, 1.0);
    float bass = 0.65 * audio(0) + 0.35 * audio(1);
    float mids = 0.55 * audio(3) + 0.45 * audio(4);
    float highs = 0.55 * audio(6) + 0.45 * audio(7);
    float response = uP3;
    float t = uTime * (0.10 + uP1 * 0.28) + mids * response * 0.55;

    vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
    float radius = length(p);
    float symmetry = max(3.0, floor(uP0 + 0.5));
    float sector = 6.2831853 / symmetry;
    float angle = atan(p.y, p.x) + t;
    angle = abs(mod(angle + sector * 0.5, sector) - sector * 0.5);
    float pulse = 1.0 + bass * response * 0.16;
    vec2 fold = vec2(cos(angle), sin(angle)) * radius * pulse;

    vec2 z = fold * (2.25 + 0.22 * sin(t * 0.7));
    vec2 constant = vec2(-0.48 + 0.08 * sin(t * 0.31), 0.56 + 0.08 * cos(t * 0.23));
    float trap = 10.0;
    float escaped = 0.0;
    float depth = clamp(uP2, 4.0, 18.0);
    for (int i = 0; i < 18; i++) {
        if (float(i) < depth && escaped < 0.5) {
            z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + constant;
            trap = min(trap, abs(length(z) - 0.72));
            if (dot(z, z) > 9.0) escaped = 1.0;
        }
    }

    float filaments = exp(-trap * (18.0 + depth * 0.8));
    float tunnel = 0.5 + 0.5 * sin(22.0 * log(radius + 0.055) - t * 5.0 + filaments * 4.0);
    float spokes = 0.5 + 0.5 * cos(angle * symmetry * 2.0 + t * 1.7);
    float pattern = clamp(filaments * 1.15 + tunnel * 0.32 + spokes * 0.18, 0.0, 1.0);

    vec2 warp = vec2(cos(angle), sin(angle)) * (0.025 + 0.035 * pattern);
    warp *= uIntensity * (0.55 + 0.45 * uEnergy);
    vec2 sampleUv = clamp(uv + warp * psyRotate(t * 0.25), vec2(0.002), vec2(0.998));
    float split = (0.0015 + highs * response * 0.006) * uIntensity;
    vec3 bent;
    bent.r = texture(uTexture, clamp(sampleUv + warp * split * 18.0, vec2(0.002), vec2(0.998))).r;
    bent.g = texture(uTexture, sampleUv).g;
    bent.b = texture(uTexture, clamp(sampleUv - warp * split * 18.0, vec2(0.002), vec2(0.998))).b;

    float hue = fract(radius * 1.85 - t * 0.12 + pattern * 0.48 + mids * 0.18);
    vec3 color = psySpectrum(hue);
    float sparkle = pow(max(0.0, sin((angle + radius * 9.0) * symmetry + t * 3.0)), 18.0);
    sparkle *= highs * response;
    vec3 psychedelic = mix(bent, color * (0.52 + pattern * 0.92), 0.35 + pattern * 0.48);
    psychedelic += palette(7) * sparkle * 0.75;
    psychedelic += color * filaments * (0.20 + bass * response * 0.32);

    float vignette = smoothstep(1.05, 0.18, radius);
    float strength = clamp(uIntensity * (0.72 + 0.28 * uEnergy), 0.0, 1.0);
    vec3 outRgb = mix(src.rgb, psychedelic, strength * (0.58 + 0.34 * vignette));
    return vec4(outRgb, src.a);
}

vec3 emberLayer(vec2 uv, float aspect, float seed, float dens, float speed, float glowSize, float thresh) {
    vec2 st = uv * vec2(aspect, 1.0) * dens;
    st.x += sin(uTime * 0.043 + seed * 3.17) * 0.45;
    st.y += uTime * speed;
    vec2 cell = floor(st);
    vec2 f = st - cell;
    vec3 acc = vec3(0.0);
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            vec2 g = vec2(float(i), float(j));
            vec2 id = cell + g;
            float r = hash21(id + vec2(seed * 17.3, seed * 5.1));
            if (r < thresh) continue;
            vec2 off = vec2(hash21(id + vec2(3.7, 1.9)), hash21(id + vec2(9.1, 5.3)));
            off.x += 0.14 * sin(uTime * 0.19 + r * 24.0);
            off.y += 0.06 * sin(uTime * 0.11 + r * 11.0);
            vec2 d2 = f - g - off;
            float d = length(d2);
            float sv = max(glowSize * (0.55 + 0.9 * hash21(id + vec2(2.2, 8.8))), 0.002);
            float core = exp(-(d * d) / (sv * sv) * 2.6);
            float halo = exp(-d / (sv * 3.0));
            float tw = 0.62 + 0.38 * sin(uTime * 0.33 + r * 31.0);
            vec3 col = mix(palette(5), palette(7), hash21(id + vec2(4.4, 6.6)));
            acc += col * (core + halo * 0.30) * tw;
        }
    }
    return acc;
}

vec4 effect(vec2 uv, vec4 src) {
    float aspect = uResolution.x / max(uResolution.y, 1.0);
    float dens = max(uP0, 2.0);
    float spd = uP1;
    float gs = uP2;

    vec3 g = vec3(0.0);
    g += emberLayer(uv, aspect, 1.0, dens, spd, gs, 0.80) * 1.00;
    g += emberLayer(uv, aspect, 2.0, dens * 1.63, spd * 0.62, gs * 0.72, 0.84) * 0.55;
    g += emberLayer(uv, aspect, 3.0, dens * 0.71, spd * 1.41, gs * 1.35, 0.88) * 0.35;

    // soft vertical fade so motes appear and dissolve rather than pop at edges
    float fade = smoothstep(0.0, 0.22, uv.y) * smoothstep(1.0, 0.72, uv.y);
    float breath = 0.85 + 0.15 * sin(uTime * 0.07);
    float lift = 0.30 + 0.70 * uEnergy;
    float snd = 1.0 + 0.25 * audio(1);

    g *= uP3 * uIntensity * fade * breath * lift * snd;

    // mostly behind the scene, with a faint bleed through solid areas
    float behind = 1.0 - src.a * 0.85;
    return vec4(src.rgb + g * behind, src.a);
}

float causticField(vec2 p, float t){
    float v = 0.0;
    float amp = 1.0;
    float sum = 0.0;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        vec2 q = p * (1.0 + fi * 0.75);
        q += vec2(sin(t * 0.13 + fi * 1.7), cos(t * 0.11 + fi * 2.3)) * 0.7;
        float n = noise21(q + vec2(t * 0.06 * (1.0 + fi * 0.25), -t * 0.045 - fi * 3.1));
        v += amp * sin(6.2831853 * (n * 1.4 + t * 0.035 * (1.0 + fi * 0.3) + fi * 0.21));
        sum += amp;
        amp *= 0.55;
    }
    return v / max(sum, 0.0001);
}

vec4 effect(vec2 uv, vec4 src) {
    float aspect = uResolution.x / max(uResolution.y, 1.0);
    float scale = mix(1.5, 9.0, clamp(uP0, 0.0, 1.0));
    float t = uTime * mix(0.15, 1.2, clamp(uP1, 0.0, 1.0));

    vec2 p = vec2(uv.x * aspect, uv.y) * scale;

    float e = 0.055;
    float c  = causticField(p, t);
    float cx = causticField(p + vec2(e, 0.0), t);
    float cy = causticField(p + vec2(0.0, e), t);

    float amp = uIntensity * (0.35 + 0.65 * uEnergy);

    // gentle lensing along the caustic gradient
    vec2 grad = vec2(cx - c, cy - c) / e;
    float lens = uP2 * 0.006 * amp;
    vec2 off = grad * lens;
    off += vec2(sin(t * 0.21 + uv.y * 3.1), cos(t * 0.17 + uv.x * 2.7)) * lens * 0.35;

    vec2 uv2 = clamp(uv + off, vec2(0.001), vec2(0.999));
    vec4 bent = texture(uTexture, uv2);

    // slight chromatic spread for a watery feel
    float ca = lens * 0.5;
    bent.r = texture(uTexture, clamp(uv + off * (1.0 + ca * 40.0), vec2(0.001), vec2(0.999))).r;
    bent.b = texture(uTexture, clamp(uv + off * (1.0 - ca * 40.0), vec2(0.001), vec2(0.999))).b;

    vec4 col = mix(src, bent, clamp(uIntensity, 0.0, 1.0));

    // caustic light bands: ridged, sharpened
    float ridge = 1.0 - abs(c);
    ridge = pow(clamp(ridge, 0.0, 1.0), mix(2.0, 9.0, clamp(uP3, 0.0, 1.0)));

    float band = ridge * (0.55 + 0.45 * audio(2));
    vec3 lightCol = mix(palette(5), palette(7), 0.55 + 0.45 * ridge);
    vec3 shade = palette(2);

    float glow = band * amp * 0.55;
    float dip = (1.0 - ridge) * amp * 0.05;

    vec3 rgb = col.rgb + lightCol * glow * col.a + lightCol * glow * 0.25;
    rgb = mix(rgb, shade * col.a, dip);

    return vec4(rgb, col.a);
}

vec3 tapRGB(vec2 p){ return texture(uTexture, clamp(p, vec2(0.0), vec2(1.0))).rgb; }

vec3 phosphorGlow(vec2 uv, float rad){
    vec3 g = vec3(0.0);
    for(int i = 0; i < 12; i++){
        float a = float(i) * 0.5235988;
        float ring = (i < 6) ? 1.0 : 2.0;
        g += tapRGB(uv + vec2(cos(a), sin(a)) * rad * ring);
    }
    return g / 12.0;
}

vec4 effect(vec2 uv, vec4 src){
    vec2 c = uv - 0.5;
    float r2 = dot(c, c);
    float amp = uIntensity * (0.35 + 0.65 * uEnergy);

    // --- chromatic aberration, strongest toward the edges ---
    float ab = uP2 * 0.006 * (0.15 + r2 * 3.0) * uIntensity;
    vec3 col;
    col.r = tapRGB(uv + c * ab).r;
    col.g = src.g;
    col.b = tapRGB(uv - c * ab).b;

    // --- soft phosphor bloom, tinted by the light end of the ramp ---
    float rad = 0.0015 + uP3 * 0.006;
    vec3 g = phosphorGlow(uv, rad);
    float lum = dot(g, vec3(0.299, 0.587, 0.114));
    vec3 tint = mix(palette(5), palette(7), 0.5 + 0.5 * lum);
    col += g * tint * uP3 * 0.55 * (0.6 + 0.4 * uEnergy) * uIntensity;

    // --- rolling scanlines ---
    float lines = uResolution.y * 0.28;
    float roll = uTime * uP1 * 0.035;
    float scan = sin((uv.y - roll) * lines * 6.2831853);
    float depth = uP0 * 0.5 * amp;
    col *= 1.0 - depth * (0.5 + 0.5 * scan);

    // --- slow drifting retrace band ---
    float bandPos = fract(uv.y * 0.5 - uTime * uP1 * 0.012);
    float band = exp(-pow((bandPos - 0.5) * 7.0, 2.0));
    col += palette(4) * band * 0.05 * amp;
    col *= 1.0 + band * 0.06 * amp;

    // --- gentle vignette toward the darkest ramp step ---
    float vig = smoothstep(0.95, 0.18, r2 * 1.9);
    col = mix(palette(0) * src.a, col, mix(1.0, vig, 0.75 * uIntensity));

    // faint interference shimmer, settles as energy drops
    float sh = (noise21(vec2(uv.y * 180.0, uTime * 1.7)) - 0.5) * 0.02 * amp;
    col += sh * src.a;

    vec4 outc = vec4(col, src.a);
    return mix(src, outc, uIntensity);
}

float shaftFall(float t){
    return smoothstep(0.85, -0.75, t);
}

vec4 effect(vec2 uv, vec4 src){
    float asp = uResolution.x / max(uResolution.y, 1.0);
    vec2 p = (uv - 0.5) * vec2(asp, 1.0);

    // shaft orientation: falls downward, tilted by uP0 degrees
    float a = radians(uP0);
    vec2 dir = vec2(sin(a), -cos(a));
    vec2 nrm = vec2(cos(a), sin(a));

    // very slow non-repeating sway of the beam
    float sway = sin(uTime * 0.033) * 0.055 + sin(uTime * 0.0187 + 1.7) * 0.032;
    float d = dot(p, nrm) + sway * (0.35 + 0.9 * uEnergy);

    float w = max(uP1, 0.02);
    float core = exp(-(d * d) / (w * w));
    float halo = exp(-(d * d) / (w * w * 7.0)) * 0.45;

    float t = dot(p, dir);
    float fall = shaftFall(t);

    // gentle internal banding, barely visible
    float band = 1.0 + 0.10 * sin(d * 9.0 + uTime * 0.11) * fall;

    float shaft = (core + halo) * fall * band;
    shaft *= 1.0 + 0.18 * audio(1) * uEnergy;

    // drifting dust motes, only lit where the shaft is
    float dust = 0.0;
    for(int i = 0; i < 3; i++){
        float fi = float(i);
        float sc = 26.0 + fi * 17.0;
        vec2 drift = vec2(0.014 + 0.006 * fi, -0.007 - 0.004 * fi) * uTime * max(uP3, 0.0);
        vec2 q = (p + drift) * sc + fi * 13.7;
        vec2 cell = floor(q);
        vec2 f = fract(q) - 0.5;
        float r1 = hash21(cell + fi * 31.0);
        float r2 = hash21(cell + fi * 17.0 + 5.3);
        vec2 c = (vec2(r1, r2) - 0.5) * 0.72;
        float dd = length(f - c);
        float breath = 0.55 + 0.45 * sin(uTime * (0.25 + r1 * 0.45) + r2 * 6.2831);
        float m = smoothstep(0.17, 0.0, dd) * step(0.74, r1) * breath;
        dust += m * (1.0 - fi * 0.26);
    }
    dust *= max(uP2, 0.0);

    vec3 glow = palette(5) * shaft * 0.26
              + palette(6) * shaft * 0.22
              + palette(7) * shaft * shaft * 0.20;
    glow += palette(7) * dust * shaft * 1.15;

    float amp = uIntensity * (0.35 + 0.65 * uEnergy);
    return vec4(src.rgb + glow * amp, src.a);
}

float auroraFbm(vec2 p){
    float s = 0.0;
    float a = 0.5;
    for (int i = 0; i < 4; i++) {
        s += a * noise21(p);
        p = p * 2.03 + vec2(1.7, -0.9);
        a *= 0.5;
    }
    return s;
}

vec4 effect(vec2 uv, vec4 src) {
    float density = uP0;
    float speed   = uP1;
    float height  = uP2;
    float glowAmt = uP3;

    float t = uTime * speed;

    // slow lateral sway of the whole veil
    float sway = sin(t * 0.031 + uv.y * 1.4) * 0.12
               + sin(t * 0.017 - uv.y * 2.7) * 0.06;

    // y strongly compressed -> features elongate into vertical curtains
    vec2 q = vec2(uv.x * density + sway, uv.y * 0.30 - t * 0.012);
    float n1 = auroraFbm(q);
    float n2 = auroraFbm(q * 1.83 + vec2(4.2, t * 0.019));

    float curtain = max(n1 * 0.75 + n2 * 0.45 - 0.34, 0.0);
    curtain = pow(curtain, 1.7) * 2.2;

    // fine filaments inside the curtains
    float fil = auroraFbm(vec2(uv.x * density * 3.1 + sway * 2.0, uv.y * 0.9 - t * 0.02));
    curtain *= 0.72 + 0.55 * fil;

    // vertical placement: fade in from the horizon line, soften near the top
    float base = 1.0 - clamp(height, 0.05, 1.0);
    float mask = smoothstep(base, base + 0.28, uv.y);
    mask *= 1.0 - 0.45 * smoothstep(0.80, 1.0, uv.y);

    // slow, non-repeating breath
    float breath = 0.62
                 + 0.24 * sin(uTime * 0.061)
                 + 0.14 * sin(uTime * 0.023 + 1.9);

    float band = 0.85 + 0.30 * audio(1) + 0.18 * audio(4);

    float g = curtain * mask * breath * band;
    g *= glowAmt * uIntensity * (0.30 + 0.70 * uEnergy);
    g = clamp(g, 0.0, 1.0);

    // palette-derived cool veil colour, brighter in the dense cores
    vec3 col = mix(palette(3), palette(5), smoothstep(0.0, 0.55, curtain));
    col = mix(col, palette(7), smoothstep(0.60, 1.30, curtain) * 0.55);
    col = mix(col, palette(4), 0.25 * (1.0 - uv.y));

    vec3 outRgb = src.rgb + col * g * 0.85;
    float outA = min(1.0, src.a + g * 0.5);
    return vec4(outRgb, outA);
}

float dropsLayer(vec2 p, float t, float scale, float seed, float trailAmt){
    vec2 q = vec2(p.x*scale, p.y*scale*0.6);
    float col = floor(q.x);
    float cr = hash11(col*7.31 + seed*3.7);
    float yy = q.y + t*(0.35 + 0.85*cr);
    float row = floor(yy);
    float h = 0.0;
    for(int k=0;k<2;k++){
        float rw = row - float(k);
        float rr = hash21(vec2(col*1.7 + seed, rw*2.3));
        float rx = col + 0.5 + (rr - 0.5)*0.5;
        float ry = rw + 0.5 + (hash11(rr*31.7 + seed) - 0.5)*0.5;
        vec2 d = vec2(q.x - rx, yy - ry);
        float rad = 0.13 + 0.18*rr;
        float drop = smoothstep(rad, rad*0.2, length(d*vec2(1.0,1.3)));
        float wob = 0.03*sin(d.y*9.0 + rr*22.0 + t*1.1);
        float tw = 0.03 + 0.045*rr;
        float trail = smoothstep(tw, 0.0, abs(d.x + wob));
        trail *= smoothstep(1.15, 0.04, d.y) * step(0.0, d.y);
        trail *= 0.55 + 0.45*sin(d.y*14.0 - rr*11.0);
        h = max(h, max(drop, trail*trailAmt));
    }
    return h;
}

float glassHeight(vec2 p, float t, float dens, float trailAmt){
    float h = dropsLayer(p, t, 7.0*dens, 0.0, trailAmt);
    h = max(h, dropsLayer(p, t*1.27, 11.0*dens, 4.7, trailAmt)*0.8);
    h = max(h, dropsLayer(p, t*0.81, 17.0*dens, 9.1, trailAmt)*0.55);
    return h;
}

vec4 effect(vec2 uv, vec4 src){
    float amp = uIntensity*(0.35 + 0.65*uEnergy);
    float ar  = uResolution.x/max(uResolution.y, 1.0);
    vec2  p   = vec2(uv.x*ar, uv.y);
    float t   = uTime*uP0;
    float dens = max(uP1, 0.2);

    float px = 1.4/max(uResolution.y, 1.0);
    float h  = glassHeight(p, t, dens, 0.8);
    float hx = glassHeight(p + vec2(px,0.0), t, dens, 0.8) - glassHeight(p - vec2(px,0.0), t, dens, 0.8);
    float hy = glassHeight(p + vec2(0.0,px), t, dens, 0.8) - glassHeight(p - vec2(0.0,px), t, dens, 0.8);
    vec2  g  = clamp(vec2(hx,hy)/(2.0*px), -60.0, 60.0);

    // soft defocus between the droplets
    float br = uP3*0.011*(1.0 - 0.65*h);
    vec4 blur = vec4(0.0);
    for(int i=0;i<8;i++){
        float fi = float(i);
        float a  = fi*2.3999 + uTime*0.04;
        float r  = br*sqrt((fi + 0.5)/8.0);
        vec2 o   = vec2(cos(a)/ar, sin(a))*r;
        blur += texture(uTexture, clamp(uv + o, 0.002, 0.998));
    }
    blur /= 8.0;

    vec4 base = mix(src, blur, clamp(uIntensity, 0.0, 1.0)*0.9);

    // refraction through each bead
    vec2 ro = -g*uP2*0.0055*amp;
    ro.x /= ar;
    vec4 refr = texture(uTexture, clamp(uv + ro, 0.002, 0.998));

    float m   = smoothstep(0.06, 0.45, h);
    float rim = clamp(length(g)*0.012, 0.0, 1.0)*smoothstep(0.04, 0.5, h);

    vec4 col = mix(base, refr*1.04, clamp(m*amp, 0.0, 1.0));
    col.rgb += palette(7)*rim*0.09*amp;
    col.rgb += palette(6)*h*0.025*amp;
    col.rgb = mix(col.rgb, col.rgb*0.95 + palette(1)*0.05, uIntensity*0.45);
    col.a = src.a;
    return col;
}
